const out = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(out, '../../..');
const ids = ['e13c3cb65c28', 'd4b0c4f9d75f', '94e7a19d8878', 'eca18e5843e2', 'd0d500126a80', '39adb0cfa84e', '48bdcebcffc6'];
const docs = Object.fromEntries(await Promise.all(ids.map(async id => [id, JSON.parse(await fs.readFile(path.join(root, 'data/extracted', `article-${id}.json`), 'utf8'))])));
const H = 'e13c3cb65c28', S = 'd4b0c4f9d75f', A = '94e7a19d8878', C = 'eca18e5843e2', G = 'd0d500126a80', R = '39adb0cfa84e', I = '48bdcebcffc6';
const page = (id, number) => docs[id].pages.find(item => item.page === number).text;
function excerpt(id, number, start, end) {
  const text = page(id, number), from = text.indexOf(start), last = text.indexOf(end, from);
  if (from < 0 || last < from) throw new Error(`${id} p${number}: trecho não encontrado (${start} / ${end})`);
  return { page: number, text: text.slice(from, last + end.length) };
}
const whole = (id, ...numbers) => numbers.map(number => ({ page: number, text: page(id, number) }));
const h = (number, start, end) => excerpt(H, number, start, end);
const ref = (id, sections, quotes) => ({ file: docs[id].file, title: docs[id].title, pages: [...new Set(quotes.map(item => item.page))], sections, evidence: quotes.map(item => item.text) });
const cards = [];
